window.SBS_DATA = {"track":{"id":"web","page":"web.html","nav":"HTML + CSS","langs":["html","css"],"default_langs":["html","css"]},"concepts":[{"id":"page-skeleton","level":"intro","topic":"Page structure","title":"Page skeleton"},{"id":"headings-paragraphs","level":"intro","topic":"Text","title":"Headings and paragraphs"},{"id":"links-images","level":"intro","topic":"Content","title":"Links and images"},{"id":"lists","level":"intro","topic":"Content","title":"Lists"},{"id":"selectors-basic","level":"intro","topic":"Selectors","title":"Select elements, classes, and ids"},{"id":"colors-units","level":"intro","topic":"Styling","title":"Colors and units"},{"id":"box-model","level":"intro","topic":"Layout","title":"The box model"},{"id":"semantic-layout","level":"intro","topic":"Page structure","title":"Semantic layout tags"},{"id":"forms","level":"intermediate","topic":"Forms","title":"Forms and inputs"},{"id":"tables","level":"intermediate","topic":"Content","title":"Tables"},{"id":"flexbox","level":"intermediate","topic":"Layout","title":"Flexbox"},{"id":"grid","level":"intermediate","topic":"Layout","title":"CSS grid"},{"id":"pseudo-classes","level":"intermediate","topic":"Selectors","title":"Pseudo-classes: states and positions"},{"id":"cascade-specificity","level":"intermediate","topic":"Selectors","title":"Cascade and specificity"},{"id":"positioning","level":"intermediate","topic":"Layout","title":"Positioning"},{"id":"media-queries","level":"intermediate","topic":"Responsive","title":"Responsive layout with media queries"},{"id":"custom-properties","level":"advanced","topic":"Styling","title":"Custom properties (CSS variables)"},{"id":"transitions","level":"advanced","topic":"Motion","title":"Transitions"},{"id":"keyframes","level":"advanced","topic":"Motion","title":"Keyframe animations"},{"id":"accessible-markup","level":"advanced","topic":"Accessibility","title":"Accessible forms and images"},{"id":"grid-areas","level":"advanced","topic":"Layout","title":"Grid template areas"},{"id":"transforms","level":"advanced","topic":"Motion","title":"Transforms"},{"id":"dark-mode","level":"advanced","topic":"Responsive","title":"Dark mode with prefers-color-scheme"},{"id":"fluid-type","level":"brilliant","topic":"Responsive","title":"Fluid sizing with clamp()"},{"id":"container-queries","level":"brilliant","topic":"Responsive","title":"Container queries"},{"id":"has-selector","level":"brilliant","topic":"Selectors","title":"The :has() selector"},{"id":"cascade-layers","level":"brilliant","topic":"Selectors","title":"Cascade layers"},{"id":"dialog-popover","level":"brilliant","topic":"Content","title":"Dialog and popover"},{"id":"scroll-snap","level":"brilliant","topic":"Layout","title":"Scroll snap"}],"examples":{"html":{"page-skeleton":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Maya's CS Portfolio</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Maya's CS Portfolio</h1>\n    <p>Projects from Computer Science 1 at Vista Ridge.</p>\n  </body>\n</html>","summary":"Every web page starts with the same skeleton: a doctype, an html element, a head with information about the page, and a body with what people see.","notes":["<!DOCTYPE html> tells the browser to use modern HTML rules.","Everything inside <head> is information about the page. Only <body> content shows on screen.","The <link> tag loads style.css, so the CSS file styles this page."],"pitfall":"Putting visible content like <h1> inside <head> instead of <body> is invalid HTML, and browsers move or ignore it.","keywords":["doctype","html","head","body","title","meta","link","skeleton","boilerplate"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":160,"mode":null,"filename":null},"headings-paragraphs":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Vista Ridge CS Club</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- Use one h1 per page for the main title. -->\n    <h1>Vista Ridge CS Club</h1>\n    <p>We build apps, games, and websites every Tuesday after school.</p>\n\n    <!-- h2 starts a section. Pick the level by structure, not by size. -->\n    <h2>Meetings</h2>\n    <p>Room 2115, 3:45 to 5:00 PM. Bring a laptop if you have one.</p>\n\n    <h2>Who can join</h2>\n    <p>Any student. You do not need to know how to code yet.</p>\n    <!-- strong marks important text. em adds stress to a word. -->\n    <p><strong>New members:</strong> come to the <em>first</em> meeting of the month.</p>\n  </body>\n</html>","summary":"Headings (h1 to h6) give a page its outline, and p holds a paragraph of text. Browsers and screen readers use the heading levels to understand how the page is organized.","notes":["Use one <h1> for the page title, then <h2> for each section. Do not skip levels (h2 straight to h4).","Each <p> is its own paragraph. Pressing Enter in your code does not make a new paragraph on screen; a new <p> does.","<strong> and <em> add meaning (important, stressed). The bold and italic look comes from the browser's default styles."],"pitfall":"Picking <h4> because it looks the right size. The heading level describes structure; change the size in CSS instead.","keywords":["h1","h2","h3","heading","p","paragraph","strong","em","bold","italic","text"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":330,"mode":null,"filename":null},"links-images":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Links</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- src is the image. alt describes it for screen readers and shows if it fails to load.\n         This src is a small SVG written as a data: URI, so no image file is needed. -->\n    <img src=\"data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20width='80'%20height='80'%3E%3Ccircle%20cx='40'%20cy='40'%20r='38'%20fill='%231d4e89'/%3E%3Ctext%20x='40'%20y='50'%20font-size='28'%20font-family='sans-serif'%20text-anchor='middle'%20fill='white'%3ECS%3C/text%3E%3C/svg%3E\"\n         alt=\"CS Club logo: the letters CS in a blue circle\" width=\"80\" height=\"80\">\n    <h1>CS Club links</h1>\n\n    <!-- href is where the link goes. The text between the tags is what people click. -->\n    <p>Sign up on the <a href=\"https://example.com/cs-club\">club page</a>.</p>\n\n    <!-- target=\"_blank\" opens the page in a new tab. Say so in the text. -->\n    <p><a href=\"https://example.com/projects\" target=\"_blank\">Last year's projects</a> (opens in a new tab)</p>\n\n    <!-- # plus an id jumps to that element on the same page. -->\n    <p><a href=\"#contact\">Jump to contact info</a></p>\n\n    <h2 id=\"contact\">Contact</h2>\n    <p>Email <a href=\"mailto:csclub@example.com\">csclub@example.com</a></p>\n  </body>\n</html>","summary":"The <a> tag makes a link and the <img> tag shows an image. A link needs href (where to go), and an image needs src (the file) and alt (a text description).","notes":["alt should say what the image shows or does. Screen readers read it aloud, and it appears if the image fails to load.","href=\"#contact\" jumps to the element with id=\"contact\" on the same page. mailto: opens an email app.","Set width and height on <img> so the page saves the right space before the image loads."],"pitfall":"Leaving out alt. Screen readers then read the file name, and for a data: URI that is a long string of code.","keywords":["a","href","link","anchor","img","src","alt","image","target","_blank","mailto","data uri","svg"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":390,"mode":null,"filename":null},"lists":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Plans</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>CS Club plans</h1>\n    <h2>This semester we will learn</h2>\n    <!-- ul is an unordered list: the order does not matter. -->\n    <ul>\n      <li>HTML and CSS</li>\n      <li>Python games</li>\n      <li>Robotics\n        <!-- A nested list goes inside an li, not directly inside the ul. -->\n        <ul>\n          <li>Sensors</li>\n          <li>Motors</li>\n        </ul>\n      </li>\n    </ul>\n    <h2>How to join</h2>\n    <!-- ol is an ordered list: the browser numbers the steps for you. -->\n    <ol>\n      <li>Fill out the sign-up form.</li>\n      <li>Come to a Tuesday meeting in Room 2115.</li>\n      <li>Pick a project team.</li>\n    </ol>\n  </body>\n</html>","summary":"Use <ul> for a list where order does not matter and <ol> for steps or rankings. Every item goes in its own <li>.","notes":["<ol> numbers its items automatically. If you add or remove a step, the numbers update.","A nested list goes inside an <li>. Here the Sensors and Motors list belongs to the Robotics item.","Only <li> elements can be direct children of <ul> or <ol>."],"pitfall":"Typing the numbers yourself (\"1. Fill out...\") inside an <ol>. The page then shows each number twice.","keywords":["ul","ol","li","list","bullet","numbered list","nested list","unordered","ordered"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":380,"mode":null,"filename":null},"selectors-basic":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Members</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Club members</h1>\n    <!-- An id is unique: only one element on the page can have id=\"president\". -->\n    <p id=\"president\">Maya Lopez, president</p>\n    <!-- A class can be reused on many elements. -->\n    <p class=\"officer\">Jordan Lee, vice president</p>\n    <p class=\"officer\">Priya Patel, treasurer</p>\n    <!-- One element can have several classes, separated by spaces. -->\n    <p class=\"officer new\">Diego Ramirez, secretary</p>\n    <p>Aisha Khan, member</p>\n    <p class=\"new\">Sam Nguyen, member</p>\n  </body>\n</html>","summary":"The class and id attributes give CSS a way to pick specific elements. Use a class for a group of elements and an id for one unique element.","notes":["id=\"president\" must appear only once on the page.","class=\"officer\" is on three paragraphs, so one CSS rule styles all three.","class=\"officer new\" gives one element two classes. It gets the styles of both."],"pitfall":"Using the same id on two elements. The page still shows, but it is invalid HTML and links like href=\"#president\" only find the first one.","keywords":["class","id","attribute","multiple classes","unique"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":280,"mode":null,"filename":null},"colors-units":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Colors</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Club colors</h1>\n    <!-- Each paragraph uses a different way to write a color. -->\n    <p class=\"named\">Named color: navy</p>\n    <p class=\"hex\">Hex: #a33a00</p>\n    <p class=\"rgb\">rgb(): rgb(46, 125, 50)</p>\n    <p class=\"hsl\">hsl(): hsl(270, 50%, 40%)</p>\n    <p class=\"see-through\">rgb() with alpha: 25% opacity</p>\n\n    <!-- These two paragraphs show sizes in rem and %. -->\n    <p class=\"big\">This text is 1.5rem: 1.5 times the root font size.</p>\n    <p class=\"half\">This box is 50% as wide as the page body.</p>\n  </body>\n</html>","summary":"This page gives each paragraph a class so the CSS file can show a different color format or unit on each one.","notes":["The class names describe what each line demonstrates, which makes the CSS easier to read.","The text in each paragraph matches the value the CSS uses, so you can compare them.","Colors and sizes live in the CSS file, not in the HTML."],"pitfall":"Trying to set colors in HTML with old attributes like <font color=\"red\">. That tag is obsolete; use CSS.","keywords":["class","color","units","style"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":380,"mode":null,"filename":null},"box-model":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Box Model</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- Every element is a box: content, then padding, then border, then margin. -->\n    <section class=\"card\">\n      <h2>Next meeting</h2>\n      <p>Tuesday, 3:45 PM, Room 2115</p>\n    </section>\n\n    <!-- Both boxes below have width: 300px in the CSS.\n         They come out different sizes because of box-sizing. -->\n    <div class=\"box content-box\">content-box: 300 + 40 padding + 8 border = 348px wide</div>\n    <div class=\"box border-box\">border-box: 300px wide, padding and border included</div>\n  </body>\n</html>","summary":"Every HTML element is drawn as a rectangle. The box model describes the layers of that rectangle: content, padding, border, and margin.","notes":["<section> groups related content with its own heading.","<div> is a plain box with no meaning. Use it when no semantic tag fits, like these demo boxes.","Each box's text tells you how its width is calculated, so you can compare it with the preview."],"pitfall":"Adding empty <br> tags or blank paragraphs to make space. Use margin and padding in CSS instead.","keywords":["div","section","box","container"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":370,"mode":null,"filename":null},"semantic-layout":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Vista Ridge CS Club</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- header: the top of the page. nav: the main links. -->\n    <header>\n      <h1>Vista Ridge CS Club</h1>\n      <nav>\n        <a href=\"#news\">News</a> <a href=\"#projects\">Projects</a> <a href=\"#join\">Join</a>\n      </nav>\n    </header>\n    <!-- main: the content that is unique to this page. Use it once. -->\n    <main>\n      <!-- article: a piece that makes sense on its own, like a news post. -->\n      <article id=\"news\">\n        <h2>Hackathon on Nov 14</h2>\n        <p>Teams of three build an app in four hours. Pizza provided.</p>\n      </article>\n      <!-- aside: related extra content, like a sidebar or callout. -->\n      <aside>Meetings: Tuesdays, Room 2115</aside>\n    </main>\n    <footer>Vista Ridge High School, Leander ISD</footer>\n  </body>\n</html>","summary":"Semantic tags name the parts of a page: header, nav, main, article, aside, and footer. They look like plain boxes, but screen readers and search engines use them to understand the page.","notes":["Screen reader users can jump straight to <nav> or <main>, so they skip content they do not need.","Use <main> once per page, for the content that is not repeated on every page.","<article> is for content that would make sense alone. <section> is for a themed part of a page with its own heading."],"pitfall":"Building the whole page out of <div> elements with class names like \"header\". It looks the same but gives assistive technology nothing to work with.","keywords":["header","nav","main","article","section","aside","footer","semantic","landmark","div"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":290,"mode":null,"filename":null},"forms":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Join the CS Club</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Join the CS Club</h1>\n    <!-- action is where the data is sent. Each field's name becomes its key. -->\n    <form action=\"https://example.com/signup\" method=\"post\">\n      <!-- for=\"name\" connects the label to the input with id=\"name\". -->\n      <label for=\"name\">Full name</label>\n      <input type=\"text\" id=\"name\" name=\"name\" required>\n\n      <!-- type=\"email\" brings up an email keyboard on phones and checks for an @. -->\n      <label for=\"email\">School email</label>\n      <input type=\"email\" id=\"email\" name=\"email\" placeholder=\"you@example.com\">\n\n      <label for=\"grade\">Grade</label>\n      <select id=\"grade\" name=\"grade\">\n        <option>9</option><option>10</option><option>11</option><option>12</option>\n      </select>\n\n      <!-- Wrapping the checkbox in its label makes the words clickable too. -->\n      <label class=\"check\"><input type=\"checkbox\" name=\"laptop\"> I can bring a laptop</label>\n\n      <button type=\"submit\">Sign up</button>\n    </form>\n  </body>\n</html>","summary":"A <form> collects input and sends it to a server. Each field needs a <label> so people (and screen readers) know what to type.","notes":["The label's for must match the input's id. Then clicking the label puts the cursor in the field.","name=\"email\" is the key the server receives. Without a name, the field's value is not sent.","required stops the form from submitting while the field is empty and shows a message."],"pitfall":"Using placeholder instead of a label. The hint disappears as soon as someone types, and many screen readers do not read it.","keywords":["form","input","label","for","id","name","type","email","checkbox","select","option","button","submit","required","placeholder"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":400,"mode":null,"filename":null},"tables":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Hackathon Scores</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <table>\n      <!-- caption is the table's title. Screen readers announce it first. -->\n      <caption>Fall hackathon scores</caption>\n      <thead>\n        <!-- scope=\"col\" says this header labels the cells below it. -->\n        <tr><th scope=\"col\">Team</th><th scope=\"col\">Code</th><th scope=\"col\">Design</th><th scope=\"col\">Total</th></tr>\n      </thead>\n      <tbody>\n        <!-- scope=\"row\" says this header labels the cells to its right. -->\n        <tr><th scope=\"row\">Byte Club</th><td>45</td><td>38</td><td>83</td></tr>\n        <tr><th scope=\"row\">Null Pointers</th><td>40</td><td>47</td><td>87</td></tr>\n        <tr><th scope=\"row\">Stack Overflowers</th><td>48</td><td>44</td><td>92</td></tr>\n      </tbody>\n      <tfoot>\n        <tr><th scope=\"row\">Average</th><td>44.3</td><td>43.0</td><td>87.3</td></tr>\n      </tfoot>\n    </table>\n  </body>\n</html>","summary":"Use a <table> for data in rows and columns, like a gradebook. Each <tr> is a row, <th> is a header cell, and <td> is a data cell.","notes":["<thead>, <tbody>, and <tfoot> group the header rows, data rows, and summary row.","scope=\"col\" and scope=\"row\" tell screen readers which header goes with each cell, so a score is read as \"Byte Club, Code, 45\".","<caption> must be the first thing inside <table>."],"pitfall":"Using a table to place things side by side on a page. Tables are for data; use flexbox or grid for layout.","keywords":["table","tr","td","th","thead","tbody","tfoot","caption","scope","row","column","gradebook"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":260,"mode":null,"filename":null},"flexbox":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Officers</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- The header is the flex container. Its children (h1, nav) are flex items. -->\n    <header class=\"bar\">\n      <h1>CS Club</h1>\n      <nav class=\"links\">\n        <a href=\"#officers\">Officers</a>\n        <a href=\"#projects\">Projects</a>\n        <a href=\"#join\">Join</a>\n      </nav>\n    </header>\n    <h2 id=\"officers\">Officers</h2>\n    <!-- A second flex container: the cards sit in a row and wrap when they run out of room. -->\n    <ul class=\"cards\">\n      <li>Maya Lopez<br>President</li>\n      <li>Jordan Lee<br>Vice president</li>\n      <li>Priya Patel<br>Treasurer</li>\n      <li>Diego Ramirez<br>Secretary</li>\n    </ul>\n  </body>\n</html>","summary":"Flexbox is a CSS layout, so the HTML stays plain. You only need an element to be the container and its direct children to be the items.","notes":["Only direct children become flex items. The links are items of nav, not of header.","The officers are a <ul> because they are a list, even though they display as cards.","<br> is fine here for a line break inside a short item."],"pitfall":"Putting display: flex on the items instead of their parent. Flexbox is turned on for the container.","keywords":["flex container","flex item","nav","ul","cards"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":280,"mode":null,"filename":null},"grid":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Projects</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Club projects</h1>\n    <!-- The section is the grid container. Each article is placed in a grid cell. -->\n    <section class=\"projects\">\n      <article class=\"featured\">\n        <h2>Lunch menu app</h2>\n        <p>Featured: shows today's cafeteria menu on your phone.</p>\n      </article>\n      <article><h2>Robot scoreboard</h2><p>Tracks match points.</p></article>\n      <article><h2>Study timer</h2><p>25 minutes on, 5 off.</p></article>\n      <article><h2>Club website</h2><p>The site you are on.</p></article>\n      <article><h2>Quiz bot</h2><p>Practice AP CSA terms.</p></article>\n    </section>\n  </body>\n</html>","summary":"CSS grid places items into rows and columns. In the HTML you only need a container and its child elements; the CSS decides where they go.","notes":["Each <article> is one project card and one grid item.","class=\"featured\" lets the CSS make the first card wider than the others.","The cards are in reading order in the HTML. Keep it that way so keyboard and screen reader order matches the screen."],"pitfall":"Adding empty <div> elements to fill grid cells. Grid places items automatically, so you do not need placeholders.","keywords":["grid","grid container","grid item","article","cards"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":310,"mode":null,"filename":null},"pseudo-classes":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Meetings</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Meeting schedule</h1>\n    <!-- No classes needed: :first-child and :nth-child pick rows by position. -->\n    <ul class=\"schedule\">\n      <li>Oct 7: Intro to HTML</li>\n      <li>Oct 14: CSS colors and fonts</li>\n      <li>Oct 21: Flexbox layouts</li>\n      <li>Oct 28: Build a club page</li>\n    </ul>\n    <!-- Hover, click, or Tab to these to see their states. -->\n    <p>\n      <a href=\"https://example.com/slides\">Slides</a>\n      <a href=\"https://example.com/replit\">Starter code</a>\n    </p>\n    <label for=\"topic\">Suggest a topic</label>\n    <input id=\"topic\" type=\"text\" placeholder=\"Game design?\">\n    <button type=\"button\">Send</button>\n  </body>\n</html>","summary":"Pseudo-classes style an element based on its state or position, so the HTML does not need extra classes. This page has a list, links, an input, and a button to try them on.","notes":["Move the mouse over the links and the button to see :hover.","Press Tab to move through the links, input, and button. The focused one gets an outline from :focus-visible.","type=\"button\" makes a button that does not submit a form."],"pitfall":"Adding a class like \"first\" or \"odd\" to list items by hand. Then every time you add an item you have to fix the classes; :nth-child does it automatically.","keywords":["hover","focus","state","first-child","nth-child","button","tab","keyboard"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":330,"mode":null,"filename":null},"cascade-specificity":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Announcements</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Announcements</h1>\n    <!-- Every paragraph matches the p rule. Some also match a class or id rule,\n         and the more specific rule wins the color. -->\n    <p>Only p matches: gray.</p>\n    <p class=\"note\">p and .note match: .note is more specific, so green.</p>\n    <p class=\"note\" id=\"urgent\">p, .note, and #urgent match: the id wins, so red.</p>\n    <p class=\"note reminder\">.note and .reminder tie: the rule written last wins, so blue.</p>\n    <!-- A rule on the parent is inherited only if the child has no rule of its own. -->\n    <section class=\"club-news\">\n      <p>This p has its own gray rule, so the section's purple is not used.</p>\n      <h2>This h2 has no color rule, so it inherits purple.</h2>\n    </section>\n  </body>\n</html>","summary":"When several CSS rules match the same element, the browser must pick one value for each property. Each paragraph here matches a different set of rules and says which one wins.","notes":["The second paragraph has class=\"note\", so it matches both p and .note.","The last two elements are inside <section class=\"club-news\"> to show inheritance.","Read each line, then find the matching rules in the CSS pane."],"pitfall":"Adding an id to an element only to beat another rule. It works, but the next change then needs an even stronger selector.","keywords":["cascade","specificity","class","id","inherit","conflict"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":285,"mode":null,"filename":null},"positioning":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Positioning</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- The badge is placed on the card's corner with absolute positioning. -->\n    <article class=\"card\">\n      <span class=\"badge\">New</span>\n      <h2>Game jam team</h2>\n      <p>Build a horror game in Unity over two weeks.</p>\n    </article>\n\n    <!-- Scroll inside this box: the heading sticks to its top. -->\n    <section class=\"schedule\">\n      <h2>Fall schedule</h2>\n      <p>Oct 7: Intro to HTML</p>\n      <p>Oct 14: CSS colors</p>\n      <p>Oct 21: Flexbox</p>\n      <p>Oct 28: Positioning</p>\n      <p>Nov 4: Forms</p>\n      <p>Nov 14: Hackathon</p>\n    </section>\n  </body>\n</html>","summary":"Positioning moves an element away from where it would normally appear. This page has a card with a corner badge and a scrolling schedule with a heading that stays visible.","notes":["The <span class=\"badge\"> is inside the card, which matters: absolute positioning measures from the nearest positioned ancestor.","The schedule box is short on purpose so it can scroll. Scroll inside it in the preview.","The badge text \"New\" is still in the HTML, so screen readers read it."],"pitfall":"Using absolute positioning to build a whole page layout. Positioned elements leave the normal flow, so they overlap when text grows or the screen gets narrow.","keywords":["position","badge","sticky header","scroll"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":330,"mode":null,"filename":null},"media-queries":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Projects</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Club projects</h1>\n    <!-- Only one of these three lines shows. The CSS picks it by screen width. -->\n    <p class=\"size phone\">Phone layout: under 500px, 1 column</p>\n    <p class=\"size tablet\">Tablet layout: 500px to 899px, 2 columns</p>\n    <p class=\"size desktop\">Desktop layout: 900px and wider, 4 columns</p>\n    <section class=\"projects\">\n      <article>Lunch menu app</article>\n      <article>Robot scoreboard</article>\n      <article>Study timer</article>\n      <article>Quiz bot</article>\n    </section>\n  </body>\n</html>","summary":"Media queries live in CSS, but the HTML must include the viewport meta tag or phones will pretend to be a wide desktop screen and ignore your phone layout.","notes":["<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"> tells phones to use their real width.","The preview is about 640px wide, so it shows the tablet line and two columns.","The three .size lines are only there to show which layout is active. A real site would not need them."],"pitfall":"Leaving out the viewport meta tag. On a phone the page then shows as a tiny zoomed-out desktop layout.","keywords":["viewport","meta viewport","responsive","mobile"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":270,"mode":null,"filename":null},"custom-properties":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Teams</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Project teams</h1>\n    <!-- All three cards use the same .team rule. The extra class only\n         changes the value of one variable. -->\n    <section class=\"teams\">\n      <article class=\"team\">\n        <h2>Web team</h2>\n        <p>Builds the club website.</p>\n      </article>\n      <article class=\"team games\">\n        <h2>Games team</h2>\n        <p>Makes a horror game in Unity.</p>\n      </article>\n      <article class=\"team robots\">\n        <h2>Robotics team</h2>\n        <p>Programs the competition robot.</p>\n      </article>\n    </section>\n  </body>\n</html>","summary":"The three cards share one class, team. A second class (games, robots) is a hook the CSS uses to change a variable for that card only.","notes":["class=\"team games\" gives the card both classes.","The HTML does not contain any colors. Every color comes from a variable in the CSS.","Adding a fourth team only needs a new class and one variable in the CSS."],"pitfall":"Writing a style=\"\" attribute on each card to change its color. That spreads design choices across the HTML and makes them hard to update.","keywords":["class","variant","theme","cards"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":250,"mode":null,"filename":null},"transitions":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Meetings</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Upcoming meetings</h1>\n    <!-- Hover a card, or press Tab to reach a link, to see the change animate. -->\n    <ul class=\"meetings\">\n      <li><a href=\"https://example.com/oct-21\">Oct 21: Flexbox layouts</a></li>\n      <li><a href=\"https://example.com/oct-28\">Oct 28: Build a club page</a></li>\n      <li><a href=\"https://example.com/nov-4\">Nov 4: Forms that work</a></li>\n    </ul>\n    <button type=\"button\">RSVP</button>\n  </body>\n</html>","summary":"Transitions are added in CSS. The HTML only needs elements that change state, like links and buttons people can hover or focus.","notes":["Each meeting is a link, so it can be reached with the Tab key as well as the mouse.","Hover a meeting or the RSVP button in the preview to see the colors fade.","The links fill their list items in the CSS, so the whole row is clickable."],"pitfall":"Adding hover effects to a plain <div> or <li> that is not a link or button. Keyboard users can never trigger them.","keywords":["hover","focus","link","button","interactive"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":335,"mode":null,"filename":null},"keyframes":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Sign-ups</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Hackathon sign-ups</h1>\n    <!-- This dot fades in and out to show the meeting is happening now. -->\n    <p class=\"live\"><span class=\"dot\"></span> Meeting in progress: Room 2115</p>\n\n    <!-- The bar fills once when the page loads. role and aria values let\n         screen readers announce the progress. -->\n    <p>18 of 24 spots filled</p>\n    <div class=\"track\" role=\"progressbar\" aria-valuemin=\"0\" aria-valuemax=\"24\" aria-valuenow=\"18\" aria-label=\"Hackathon spots filled\">\n      <div class=\"fill\"></div>\n    </div>\n  </body>\n</html>","summary":"Keyframe animations are written in CSS. The HTML provides the elements to animate: here, a status dot and a progress bar.","notes":["The empty <span class=\"dot\"> is only decoration. The text next to it carries the meaning.","role=\"progressbar\" with aria-valuenow tells screen readers the bar shows 18 of 24. They cannot see the width.","Nothing in the HTML starts the animation. The CSS runs it as soon as the page loads."],"pitfall":"Using motion as the only way to show information, like a blinking dot with no text. People who turn off animation, or use a screen reader, miss it.","keywords":["animation","progress bar","role","aria","status"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":220,"mode":null,"filename":null},"accessible-markup":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Hackathon Sign-up</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Hackathon sign-up</h1>\n    <!-- Informative image: alt says what it shows. Decorative image: alt=\"\" so it is skipped. -->\n    <img src=\"data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20width='120'%20height='40'%3E%3Crect%20width='120'%20height='40'%20rx='6'%20fill='%231d4e89'/%3E%3Ctext%20x='60'%20y='26'%20font-size='16'%20font-family='sans-serif'%20text-anchor='middle'%20fill='white'%3ENov%2014%3C/text%3E%3C/svg%3E\" alt=\"Hackathon date: November 14\" width=\"120\" height=\"40\">\n    <img src=\"data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20width='300'%20height='6'%3E%3Crect%20width='300'%20height='6'%20fill='%23a33a00'/%3E%3C/svg%3E\" alt=\"\" width=\"300\" height=\"6\">\n    <form action=\"https://example.com/hackathon\" method=\"post\">\n      <!-- aria-describedby links the hint, so screen readers read it with the field. -->\n      <label for=\"team\">Team name</label>\n      <input id=\"team\" name=\"team\" required aria-describedby=\"team-hint\">\n      <p id=\"team-hint\" class=\"hint\">3 to 20 letters. No school names.</p>\n      <!-- fieldset and legend give a group of radio buttons one shared question. -->\n      <fieldset>\n        <legend>Experience level</legend>\n        <label><input type=\"radio\" name=\"level\" value=\"new\"> New to coding</label>\n        <label><input type=\"radio\" name=\"level\" value=\"some\"> Some experience</label>\n      </fieldset>\n      <!-- The button text says what happens. \"Click here\" would not. -->\n      <button type=\"submit\">Register team</button>\n    </form>\n  </body>\n</html>","summary":"Accessible markup lets everyone use the page, including people using a screen reader or only a keyboard. Give images the right alt text and connect every form field to its label and hints.","notes":["The date image has alt text because it carries information. The divider line has alt=\"\" so screen readers skip it.","aria-describedby=\"team-hint\" points at the hint's id. A screen reader says \"Team name, edit text, required, 3 to 20 letters.\"","<legend> is read before each radio button, so \"New to coding\" is heard as part of the Experience level question."],"pitfall":"Leaving alt off a decorative image instead of writing alt=\"\". Without alt, screen readers read the file name or the whole data: URI.","keywords":["accessibility","a11y","alt","alt text","decorative image","label","aria-describedby","fieldset","legend","radio","screen reader","wcag"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":400,"mode":null,"filename":null},"grid-areas":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Vista Ridge CS Club</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- Each landmark gets a named area in the CSS. Their order here is the\n         reading order, even if the grid places them differently. -->\n    <div class=\"page\">\n      <header>Vista Ridge CS Club</header>\n      <nav>\n        <a href=\"#home\">Home</a>\n        <a href=\"#projects\">Projects</a>\n        <a href=\"#join\">Join</a>\n      </nav>\n      <main>\n        <h1>Welcome</h1>\n        <p>We meet Tuesdays at 3:45 PM in Room 2115.</p>\n      </main>\n      <aside>Hackathon: Nov 14</aside>\n      <footer>Leander ISD</footer>\n    </div>\n  </body>\n</html>","summary":"A full page layout starts with semantic tags for each region. The CSS then names a grid area for each one and draws the layout as a map.","notes":["The wrapper div is the grid container. header, nav, main, aside, and footer are its grid items.","Keep the HTML in a sensible reading order. Screen readers and the Tab key follow the HTML, not the grid.","The h1 is inside main, because the club name in the header is repeated on every page."],"pitfall":"Rearranging the HTML so it matches the visual layout. Leave the HTML in reading order and let grid-template-areas move things.","keywords":["page layout","header","nav","main","aside","footer","holy grail layout","sidebar"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":270,"mode":null,"filename":null},"transforms":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Board</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Club bulletin board</h1>\n    <!-- Each note uses a different transform. Hover a note to see scale(). -->\n    <section class=\"board\">\n      <article class=\"note rotate\">\n        <h2>rotate()</h2>\n        <p>Hackathon Nov 14</p>\n      </article>\n      <article class=\"note move\">\n        <h2>translate()</h2>\n        <p>New members welcome</p>\n      </article>\n      <article class=\"note grow\">\n        <h2>scale()</h2>\n        <p>Bring a laptop</p>\n      </article>\n    </section>\n  </body>\n</html>","summary":"Transforms are a CSS effect, so the HTML is three ordinary cards. Each class name says which transform its card shows.","notes":["The h2 in each card names the transform function the CSS applies to it.","Hover any card in the preview: it grows a little, and the tilted card straightens.","A transform changes how an element looks, not what it is. Screen readers read the cards the same way."],"pitfall":"Using transforms to fix layout problems, like shifting a box until it lines up. The space it takes up does not move, so other elements may overlap it.","keywords":["transform","card","hover","bulletin board"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":240,"mode":null,"filename":null},"dark-mode":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <!-- Tells the browser the page supports both themes, so built-in parts\n         like scroll bars and form fields match. -->\n    <meta name=\"color-scheme\" content=\"light dark\">\n    <title>CS Club Meetings</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>CS Club</h1>\n    <article class=\"card\">\n      <h2>Next meeting</h2>\n      <p>Tuesday, 3:45 PM in Room 2115. We are building <a href=\"https://example.com/game\">a horror game</a>.</p>\n      <label for=\"email\">Email for reminders</label>\n      <input id=\"email\" type=\"email\" placeholder=\"you@example.com\">\n    </article>\n  </body>\n</html>","summary":"A page can follow the light or dark setting of the person's device. The HTML only needs a color-scheme meta tag; the colors themselves are in the CSS.","notes":["The preview follows your own system setting. Switch your computer or phone between light and dark mode and the preview changes.","<meta name=\"color-scheme\" content=\"light dark\"> makes the input and scroll bars use dark colors in dark mode too.","The content is the same in both themes. Only the colors change."],"pitfall":"Making a separate dark copy of the page. One page with two sets of colors in the CSS is much easier to keep up to date.","keywords":["dark mode","light mode","color-scheme","meta","theme"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":305,"mode":null,"filename":null},"fluid-type":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Hackathon</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <!-- No media queries: the heading, text, and spacing grow smoothly\n         with the window width. -->\n    <header class=\"hero\">\n      <h1>Fall Hackathon</h1>\n      <p>Four hours. Teams of three. Build anything.</p>\n    </header>\n    <main class=\"details\">\n      <p>Saturday, Nov 14, 9 AM to 1 PM in the Vista Ridge library.\n         Sign up with your team by Nov 7. Pizza and snacks provided.</p>\n    </main>\n  </body>\n</html>","summary":"Fluid sizing is done entirely in CSS. The HTML is a normal page with a header and a paragraph; the CSS makes their sizes follow the window width.","notes":["There are no extra classes for small or large screens. One rule covers every width.","The viewport meta tag is still required so phones report their real width.","Open the page in a browser and resize the window to watch the heading change size."],"pitfall":"Making a separate copy of a heading for phones and hiding one of them. Screen readers may read both.","keywords":["responsive text","hero","heading","viewport"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":240,"mode":null,"filename":null},"container-queries":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Members</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <div class=\"layout\">\n      <!-- The same member card markup is used in a wide column and a narrow one. -->\n      <main class=\"slot\">\n        <p class=\"label\">main: wide container</p>\n        <article class=\"member\">\n          <svg class=\"avatar\" viewBox=\"0 0 40 40\" aria-hidden=\"true\"><circle cx=\"20\" cy=\"20\" r=\"20\" fill=\"#1d4e89\"/><text x=\"20\" y=\"26\" font-size=\"16\" text-anchor=\"middle\" fill=\"white\">ML</text></svg>\n          <div>\n            <h2>Maya Lopez</h2>\n            <p>President. Leads the web team and runs Tuesday meetings.</p>\n          </div>\n        </article>\n      </main>\n      <aside class=\"slot\">\n        <p class=\"label\">aside: narrow container</p>\n        <article class=\"member\">\n          <svg class=\"avatar\" viewBox=\"0 0 40 40\" aria-hidden=\"true\"><circle cx=\"20\" cy=\"20\" r=\"20\" fill=\"#a33a00\"/><text x=\"20\" y=\"26\" font-size=\"16\" text-anchor=\"middle\" fill=\"white\">JL</text></svg>\n          <div>\n            <h2>Jordan Lee</h2>\n            <p>Vice president. Leads the games team.</p>\n          </div>\n        </article>\n      </aside>\n    </div>\n  </body>\n</html>","summary":"A container query lets a component change its layout based on the space its container gives it, not the screen width. This page puts the same member card in a wide column and a narrow one so you can see both layouts at once.","notes":["Both <article class=\"member\"> cards have identical markup. Only the container around them differs.","The <svg> avatars are drawn inline, with aria-hidden=\"true\" because the name next to them already says who it is.","The .label lines are only there to name each container in the preview."],"pitfall":"Expecting a container query to work without marking an ancestor as a container. Some ancestor needs container-type in the CSS, or the @container rule never matches.","keywords":["container","component","card","svg","aria-hidden","sidebar"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":220,"mode":null,"filename":null},"has-selector":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Hackathon Checklist</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Hackathon checklist</h1>\n    <!-- Two boxes start checked. Click any item to check or uncheck it. -->\n    <ul class=\"checklist\">\n      <li><label><input type=\"checkbox\" checked> Join a team of three</label></li>\n      <li><label><input type=\"checkbox\" checked> Install VS Code</label></li>\n      <li><label><input type=\"checkbox\"> Charge your laptop</label></li>\n      <li><label><input type=\"checkbox\"> Read the rules</label></li>\n    </ul>\n\n    <!-- Only one of these cards contains a .badge. -->\n    <div class=\"cards\">\n      <article class=\"card\">\n        <span class=\"badge\">Full</span>\n        <h2>Web track</h2>\n      </article>\n      <article class=\"card\">\n        <h2>Games track</h2>\n      </article>\n    </div>\n  </body>\n</html>","summary":"The HTML for :has() is ordinary: checkboxes inside list items, and cards where only some contain a badge. The CSS styles the parents based on what is inside them.","notes":["The checked attribute makes the first two boxes start checked, so the preview shows both states.","Click a checklist item in the preview to see its row change style.","No classes like \"done\" are needed. The checkbox state is enough."],"pitfall":"Adding a class such as \"done\" by hand to match the checkbox. It falls out of sync as soon as someone clicks the box.","keywords":["checkbox","checked","label","card","badge"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":330,"mode":null,"filename":null},"cascade-layers":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Buttons</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Join a project</h1>\n    <!-- Each button's text says which layer decided its color. -->\n    <p>\n      <button type=\"button\" id=\"join-web\">base layer: gray</button>\n      <button type=\"button\" class=\"btn\">components layer: blue</button>\n      <button type=\"button\" class=\"btn\" id=\"join-games\">components beats the id in base: blue</button>\n      <button type=\"button\" class=\"btn danger\">utilities layer: red</button>\n      <button type=\"button\" class=\"btn special\">unlayered CSS: green</button>\n    </p>\n  </body>\n</html>","summary":"Cascade layers are set up in CSS. The HTML is a row of buttons, and each label names the layer that wins for that button.","notes":["The third button has an id and a class. Normally the id rule would win.","Compare each label with the rules in the CSS pane to see why it got that color.","type=\"button\" makes buttons that do nothing when clicked, which is all this demo needs."],"pitfall":"Adding more ids or classes in the HTML to fight a style you cannot override. With layers you can put the styles in the right order instead.","keywords":["button","class","id","layers"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":260,"mode":null,"filename":null},"dialog-popover":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Meeting Info</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Tuesday meeting</h1>\n    <!-- popovertarget names the id of the popover to open. No JavaScript needed. -->\n    <button type=\"button\" popovertarget=\"room-info\">Where is Room 2115?</button>\n\n    <!-- popover hides this until the button opens it. Click outside or press Esc to close it. -->\n    <div id=\"room-info\" popover>\n      <p>Second floor, C hall, next to the library stairs.</p>\n      <button type=\"button\" popovertarget=\"room-info\" popovertargetaction=\"hide\">Close</button>\n    </div>\n\n    <!-- open shows the dialog right away, as part of the page (not modal).\n         A modal dialog needs JavaScript: document.querySelector(\"dialog\").showModal(). -->\n    <dialog open aria-labelledby=\"rsvp-title\">\n      <h2 id=\"rsvp-title\">RSVP</h2>\n      <p>Will you come to the hackathon on Nov 14?</p>\n      <!-- method=\"dialog\" closes the dialog instead of sending the form to a server. -->\n      <form method=\"dialog\">\n        <button value=\"yes\">Yes</button>\n        <button value=\"no\">Not this time</button>\n      </form>\n    </dialog>\n  </body>\n</html>","summary":"The popover attribute and the <dialog> element show content on top of the page. A button with popovertarget opens a popover with no JavaScript. A <dialog> holds a focused task like a confirmation or a short form.","notes":["Click \"Where is Room 2115?\" in the preview to open the popover. Click outside it or press Esc to close it.","<dialog open> shows the dialog as part of the page. To show it as a modal that blocks the rest of the page, JavaScript must call showModal(), so that is not in this preview.","<form method=\"dialog\"> closes the dialog when one of its buttons is clicked, with no JavaScript. The preview may block forms, so the RSVP buttons can do nothing there; on a normal page they close the dialog."],"pitfall":"Writing popovertarget=\"#room-info\" with a #. The value is the plain id, room-info, or the button does nothing.","keywords":["popover","popovertarget","popovertargetaction","dialog","modal","showModal","method dialog","tooltip","overlay","Esc"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":330,"mode":null,"filename":null},"scroll-snap":{"code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>CS Club Project Gallery</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n  </head>\n  <body>\n    <h1>Project gallery</h1>\n    <p>Scroll sideways. Each card snaps into place.</p>\n    <!-- tabindex=\"0\" lets keyboard users focus the strip and scroll it with arrow keys.\n         The aria-label names the region for screen readers. -->\n    <section class=\"gallery\" tabindex=\"0\" aria-label=\"Club projects\">\n      <article class=\"slide\"><h2>Lunch menu app</h2><p>Today's menu on your phone.</p></article>\n      <article class=\"slide\"><h2>Robot scoreboard</h2><p>Live match points.</p></article>\n      <article class=\"slide\"><h2>Study timer</h2><p>25 minutes on, 5 off.</p></article>\n      <article class=\"slide\"><h2>Horror game</h2><p>Made in Unity by the games team.</p></article>\n      <article class=\"slide\"><h2>Quiz bot</h2><p>Practice AP CSA terms.</p></article>\n    </section>\n  </body>\n</html>","summary":"A scroll snap gallery is a normal list of cards inside one scrolling container. The CSS makes the container scroll sideways and stop on each card.","notes":["tabindex=\"0\" makes the gallery focusable, so you can click or Tab to it and use the arrow keys to scroll.","Scroll the strip sideways in the preview with a trackpad, Shift and the mouse wheel, or the arrow keys.","Every project is still in the HTML. Cards that are off screen are only scrolled out of view, not hidden."],"pitfall":"Making a scrolling area that cannot get keyboard focus. People without a mouse or trackpad then cannot reach the hidden cards.","keywords":["carousel","slider","gallery","tabindex","scroll","aria-label"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":255,"mode":null,"filename":null}},"css":{"page-skeleton":{"code":"/* A rule has a selector and declarations inside braces. */\nbody {\n  font-family: Georgia, serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\nh1 {\n  color: #1d4e89;\n}","summary":"A CSS file is a list of rules. Each rule picks elements with a selector and sets properties for them.","notes":["body { } styles the whole visible page.","Each declaration is property: value; and ends with a semicolon.","Comments in CSS go between /* and */."],"pitfall":"Forgetting a semicolon between two declarations makes the browser ignore the second one, with no error message.","keywords":["rule","selector","declaration","property","value","stylesheet","comment"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"headings-paragraphs":{"code":"body {\n  font-family: Georgia, serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n  /* Extra space between lines makes paragraphs easier to read. */\n  line-height: 1.5;\n}\n\n/* Headings are bold and large by default. Set the size you want here\n   instead of choosing a different heading level. */\nh1 {\n  color: #1d4e89;\n  font-size: 32px;\n  margin-bottom: 4px;\n}\n\nh2 {\n  color: #1d4e89;\n  font-size: 22px;\n  margin-top: 20px;\n  margin-bottom: 4px;\n}\n\n/* Paragraphs have a top and bottom margin by default. This removes the\n   top one so each paragraph sits close to its heading. */\np {\n  margin-top: 0;\n}\n\nstrong {\n  color: #a33a00;\n}","summary":"CSS controls how headings and paragraphs look: font, size, color, and spacing. The HTML level stays the same no matter how big you make it.","notes":["line-height: 1.5 sets the line spacing to 1.5 times the font size. A number with no unit scales with the text.","font-size on h1 and h2 replaces the browser's default sizes, so you never need to pick a heading level for its looks.","margin-top: 0 on p removes the default space above each paragraph."],"pitfall":"Writing font-size: 32 with no unit. The browser ignores it; most lengths need a unit like px or rem.","keywords":["font-family","font-size","line-height","color","margin","typography","heading style"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"links-images":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\n/* Images are inline by default, like a word in a sentence.\n   display: block puts the logo on its own line. */\nimg {\n  display: block;\n  margin-bottom: 8px;\n}\n\nh1 {\n  color: #1d4e89;\n  margin-top: 0;\n}\n\n/* Links are blue and underlined by default. Keep the underline so\n   people can tell a link apart from plain colored text. */\na {\n  color: #a33a00;\n  text-decoration-thickness: 2px;\n}","summary":"CSS can change how links and images look. Links get a color and underline style, and images can be switched from inline to block.","notes":["An <img> is inline by default, so text can sit next to it. display: block gives it its own line.","The a selector styles every link on the page.","text-decoration-thickness makes the underline thicker without removing it."],"pitfall":"Removing the underline with text-decoration: none. Links then look like regular text, and people miss them.","keywords":["a","link color","text-decoration","underline","img","display block","inline"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"lists":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\nh1, h2 {\n  color: #1d4e89;\n}\n\nh2 {\n  font-size: 18px;\n  margin-bottom: 4px;\n}\n\n/* list-style-type changes the bullet or number style. */\nul {\n  list-style-type: square;\n}\n\n/* The inner list matches \"ul ul\": a ul inside another ul. */\nul ul {\n  list-style-type: circle;\n}\n\n/* Lists are indented with padding on the left by default. */\nol {\n  padding-left: 24px;\n}\n\nli {\n  margin-bottom: 4px;\n}","summary":"CSS controls the marker (bullet or number) and the spacing of list items.","notes":["list-style-type sets the marker: disc, circle, square, decimal, upper-alpha, none, and more.","The selector ul ul matches a list nested inside another list, so the inner bullets can look different.","The indent comes from padding-left on the list. The markers sit inside that padding."],"pitfall":"Setting padding-left: 0 to remove the indent. The bullets then sit outside the page edge and seem to disappear.","keywords":["list-style-type","bullet style","marker","padding-left","indent","nested list","descendant selector"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"selectors-basic":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\n/* Element selector: every p on the page. */\np {\n  margin: 6px 0;\n  color: #444;\n}\n\n/* Class selector starts with a dot: every element with class=\"officer\". */\n.officer {\n  font-weight: bold;\n  color: #1d4e89;\n}\n\n/* Id selector starts with #: the one element with id=\"president\". */\n#president {\n  font-size: 22px;\n  color: #a33a00;\n}\n\n.new {\n  font-style: italic;\n}\n\n/* A group: one rule for several selectors, separated by commas. */\nh1, #president {\n  font-family: Georgia, serif;\n}","summary":"A selector chooses which elements a rule styles. p picks an element type, .officer picks a class, and #president picks one id.","notes":["A dot means class (.officer). A hash means id (#president). No symbol means element (p).","Diego has both .officer and .new, so his line is bold, blue, and italic.","h1, #president is a group: the comma means the rule applies to both."],"pitfall":"Leaving off the dot (officer { }) looks for an <officer> element, which does not exist, so nothing changes and there is no error.","keywords":["selector","class selector","id selector","element selector","type selector","dot","hash","group selector","comma"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"colors-units":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n  font-size: 16px;\n}\n\n/* Every colored line has white text and a little space inside.\n   (padding is covered in the box model lesson.) */\np {\n  color: white;\n  padding: 4px 8px;\n  margin: 6px 0;\n}\n\n/* Five ways to write a color. */\n.named { background-color: navy; }\n.hex { background-color: #a33a00; }               /* red, green, blue in hex pairs */\n.rgb { background-color: rgb(46, 125, 50); }      /* each channel 0 to 255 */\n.hsl { background-color: hsl(270, 50%, 40%); }    /* hue, saturation, lightness */\n.see-through { background-color: rgb(29 78 137 / 25%); color: #222; } /* last value is alpha */\n\n/* rem is relative to the root font size (usually 16px), so 1.5rem = 24px. */\n.big {\n  font-size: 1.5rem;\n  color: #1d4e89;\n}\n\n/* % is relative to the parent. Here, half the width of body. */\n.half {\n  width: 50%;\n  background-color: #555;\n}","summary":"CSS colors can be written as names, hex codes, rgb(), or hsl(). Sizes use units: px is fixed, rem follows the root font size, and % follows the parent element.","notes":["#a33a00 is three hex pairs: a3 red, 3a green, 00 blue. rgb(46, 125, 50) writes the same idea in decimal.","In rgb(29 78 137 / 25%) the value after the slash is alpha (opacity), so the page background shows through.","Use rem for font sizes. If someone sets a larger default font in their browser, rem text grows with it and px text does not."],"pitfall":"Writing a hex color without the # (color: a33a00;). The browser ignores the whole declaration.","keywords":["color","hex","rgb","rgba","hsl","alpha","opacity","px","rem","percent","units","named colors"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"box-model":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\n.card {\n  padding: 16px;            /* space inside the border */\n  border: 4px solid #1d4e89;\n  margin-bottom: 24px;      /* space outside the border */\n  background-color: white;  /* the background fills content and padding */\n}\n\n/* Remove the default margins so the card's padding controls the spacing. */\n.card h2, .card p {\n  margin: 0;\n}\n\n.box {\n  width: 300px;\n  padding: 20px;\n  border: 4px solid #a33a00;\n  margin-bottom: 12px;\n  background-color: #ffe9d6;\n}\n\n/* The default: width is only the content. Padding and border are added on. */\n.content-box { box-sizing: content-box; }\n\n/* width includes padding and border, so the box is exactly 300px. */\n.border-box { box-sizing: border-box; }","summary":"padding is space inside the border, border is the outline, and margin is space outside it. box-sizing decides whether width includes the padding and border.","notes":["padding: 16px; with one value sets all four sides. margin-bottom sets only one side.","With the default box-sizing: content-box, the first demo box is 300 + 20 + 20 + 4 + 4 = 348px wide.","box-sizing: border-box keeps the box at the width you wrote. Many sites set it on every element for that reason."],"pitfall":"Setting width: 100% and then adding padding. With content-box the element becomes wider than its parent and causes a sideways scroll bar.","keywords":["box model","padding","border","margin","width","box-sizing","border-box","content-box","spacing"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"semantic-layout":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 0;\n  background-color: #fdfaf3;\n}\n\n/* Style the semantic tags by name. No extra classes needed. */\nheader {\n  background-color: #1d4e89;\n  color: white;\n  padding: 12px 24px;\n}\n\n/* Only the h1 inside the header. */\nheader h1 { margin: 0 0 6px; font-size: 24px; }\n\n/* Links are inline, so they already sit side by side. */\nnav a { color: white; margin-right: 16px; }\n\nmain { padding: 8px 24px; }\n\naside {\n  border-left: 4px solid #a33a00;\n  padding: 6px 12px;\n  background-color: #ffe9d6;\n}\n\nfooter { padding: 12px 24px; color: #555; font-size: 14px; }","summary":"Semantic tags can be styled by name, the same as p or h1. This page gives the header a colored band and the aside a left border.","notes":["header h1 matches only the h1 inside the header.","Links are inline elements, so they sit side by side in the nav. margin-right spaces them out.","Semantic tags have no special look by default. All of the style here comes from this file."],"pitfall":"Expecting <aside> to appear as a sidebar on its own. Every one of these tags stacks top to bottom until you add layout CSS (flexbox or grid, later).","keywords":["header","nav","main","aside","footer","descendant selector","layout","sidebar"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"forms":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\nh1 { margin-top: 0; color: #1d4e89; }\n\n/* Labels are inline by default. display: block puts each on its own line,\n   above its field. */\nlabel {\n  display: block;\n  font-weight: bold;\n  margin-top: 12px;\n}\n\n/* Form controls do not use the page font unless you tell them to. */\ninput, select, button { font: inherit; padding: 6px; }\n\n/* An attribute selector: only inputs whose type is text or email. */\ninput[type=\"text\"], input[type=\"email\"] { width: 260px; }\n\n.check { font-weight: normal; }\n\nbutton {\n  display: block;\n  margin-top: 16px;\n  padding: 8px 20px;\n  background-color: #1d4e89;\n  color: white;\n  border: none;\n  border-radius: 4px;\n}","summary":"Forms need a little CSS to be readable: labels on their own lines, fields a consistent width, and a clear submit button.","notes":["font: inherit makes inputs and buttons use the page font. By default they use a smaller system font.","input[type=\"text\"] is an attribute selector. It matches only inputs whose type is text.","display: block on label stacks each label above its field."],"pitfall":"Setting a border: none on inputs to look clean. People can no longer see where to type.","keywords":["form style","label","input","button","font inherit","attribute selector","display block","border-radius"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"tables":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\n/* By default each cell has its own border with gaps between them.\n   collapse merges neighboring borders into one line. */\ntable {\n  border-collapse: collapse;\n  background-color: white;\n}\n\ncaption { font-weight: bold; font-size: 18px; text-align: left; margin-bottom: 8px; }\n\nth, td {\n  border: 1px solid #c9c2b4;\n  padding: 6px 12px;\n}\n\n/* Numbers line up best on the right. */\ntd { text-align: right; }\n\n/* Only the header cells inside thead get the dark background. */\nthead th { background-color: #1d4e89; color: white; }\n\n/* Row headers stay left-aligned like names in a gradebook. */\ntbody th, tfoot th { text-align: left; }\n\ntfoot { font-weight: bold; background-color: #ffe9d6; }","summary":"Tables start with no borders. Add borders and padding to the cells, and use border-collapse so neighboring borders become single lines.","notes":["border-collapse: collapse goes on the table, not on the cells.","text-align: right on td lines up the digits of the scores.","thead th matches only header cells inside thead, so the row headers in tbody keep a white background."],"pitfall":"Putting the border on table only. That draws one outline around the outside and no lines between cells.","keywords":["border-collapse","table border","th","td","padding","text-align","caption","table style"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"flexbox":{"code":"body { font-family: system-ui, sans-serif; margin: 0; background-color: #fdfaf3; }\n\n/* display: flex lines up the children in a row. */\n.bar {\n  display: flex;\n  justify-content: space-between; /* push h1 left and nav right */\n  align-items: center;            /* center them vertically */\n  padding: 8px 24px;\n  background-color: #1d4e89;\n}\n\n.bar h1 { margin: 0; color: white; font-size: 22px; }\n\n/* gap puts space between items, with none on the outer edges. */\n.links { display: flex; gap: 16px; }\n.links a { color: white; }\n\nh2 { margin: 16px 24px 8px; }\n\n.cards {\n  display: flex;\n  flex-wrap: wrap;   /* start a new row instead of squeezing */\n  gap: 12px;\n  list-style: none;\n  padding: 0 24px;\n}\n\n/* flex: 1 1 120px means grow, shrink, and start from 120px wide. */\n.cards li {\n  flex: 1 1 120px;\n  padding: 12px;\n  background-color: white;\n  border: 2px solid #1d4e89;\n  border-radius: 6px;\n}","summary":"display: flex lays out an element's children in a row (or column). justify-content spaces them along the row, align-items lines them up across it, and gap adds space between them.","notes":["justify-content: space-between puts the first item at the start, the last at the end, and spreads the extra space between.","flex-wrap: wrap lets items move to a new line when the row is full. Without it they shrink to fit.","flex: 1 1 120px lets each card grow to share the leftover width equally."],"pitfall":"Expecting align-items: center to center items left to right. In a row, justify-content controls left to right and align-items controls top to bottom.","keywords":["flexbox","display flex","justify-content","align-items","gap","flex-wrap","flex","flex-grow","flex-basis","row","navbar"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"grid":{"code":"body {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: #fdfaf3;\n}\n\nh1 { margin-top: 0; color: #1d4e89; }\n\n/* Three equal columns. 1fr means one share of the free space. */\n.projects {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 12px;\n}\n\n.projects article {\n  padding: 10px 12px;\n  background-color: white;\n  border: 2px solid #1d4e89;\n  border-radius: 6px;\n}\n\n.projects h2 { margin: 0 0 4px; font-size: 17px; }\n.projects p { margin: 0; }\n\n/* This card covers two columns. Grid moves the rest to fit around it. */\n.featured {\n  grid-column: span 2;\n  background-color: #ffe9d6;\n}","summary":"display: grid turns an element into a grid. grid-template-columns sets the columns, gap sets the space between cells, and grid-column lets one item cover more than one column.","notes":["repeat(3, 1fr) is short for 1fr 1fr 1fr: three columns that split the width equally.","Items fill the grid left to right, then start a new row. You do not have to place each one.","grid-column: span 2 makes the featured card two columns wide, so only one more card fits in the first row."],"pitfall":"Writing grid-template-columns: 3; and expecting three columns. It needs a size for each column, like repeat(3, 1fr).","keywords":["grid","display grid","grid-template-columns","fr","repeat","gap","grid-column","span","columns","rows"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"pseudo-classes":{"code":"body { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\n\n.schedule { list-style: none; padding: 0; }\n.schedule li { padding: 6px 10px; }\n\n/* :nth-child(odd) matches the 1st, 3rd, 5th... item. */\n.schedule li:nth-child(odd) { background-color: #ede6d6; }\n\n/* :first-child matches only the first item. */\n.schedule li:first-child { font-weight: bold; color: #1d4e89; }\n\na { color: #1d4e89; margin-right: 16px; }\n\n/* :hover applies while the mouse is over the element. */\na:hover { color: #a33a00; text-decoration-thickness: 3px; }\n\nlabel { margin-right: 6px; }\ninput, button { font: inherit; padding: 6px 10px; }\n\nbutton { background-color: #1d4e89; color: white; border: none; border-radius: 4px; }\nbutton:hover { background-color: #163b68; }\n\n/* :active applies while the button is being pressed. */\nbutton:active { background-color: #a33a00; }\n\n/* :focus-visible shows an outline when you reach an element with the keyboard. */\na:focus-visible, button:focus-visible, input:focus-visible {\n  outline: 3px solid #a33a00;\n  outline-offset: 2px;\n}","summary":"A pseudo-class starts with a colon and matches elements in a certain state (:hover, :focus-visible, :active) or position (:first-child, :nth-child()).","notes":["a:hover changes link color while the mouse is over it. Hover over Slides or Starter code in the preview.","Press Tab in the preview: :focus-visible draws an orange outline on the focused link, input, or button.","li:nth-child(odd) shades every other row, which makes long lists easier to scan."],"pitfall":"Removing outlines with outline: none and nothing in its place. Keyboard users can no longer see where they are on the page.","keywords":[":hover",":focus",":focus-visible",":active",":first-child",":nth-child","odd","even","pseudo-class","zebra stripes","outline"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"cascade-specificity":{"code":"body { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\np { margin: 6px 0; }\n\n/* Specificity, weakest to strongest:\n   element (p) < class (.note) < id (#urgent). */\n\n/* The id rule is written first on purpose. It still wins,\n   because specificity is checked before order. */\n#urgent { color: #c62828; font-weight: bold; }\n\n.note { color: #2e7d32; }\n\n/* Element selector: the weakest, so any class or id rule beats it. */\np { color: #555; }\n\n/* Same specificity as .note. When there is a tie, the later rule wins. */\n.reminder { color: #1d4e89; }\n\n/* color is inherited by children that do not set their own color. */\n.club-news { color: #6a1b9a; border-top: 2px solid #ccc; }\n.club-news h2 { font-size: 16px; margin: 6px 0; }","summary":"The cascade decides which rule wins when rules conflict. First the more specific selector wins (id beats class beats element). If they tie, the rule that comes later in the file wins.","notes":["#urgent is written above .note and p, but it wins because an id is more specific than a class or element.",".note and .reminder are both one class, so .reminder wins because it comes later.","The section's purple is inherited by the h2, but not by the p, because p { color: #555; } targets the p directly. A direct rule always beats an inherited value."],"pitfall":"Using !important to force a style. It beats normal specificity, so the only way to override it later is another !important. Fix the selector instead.","keywords":["cascade","specificity","!important","inheritance","inherit","source order","id","class","selector weight","override"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"positioning":{"code":"body { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh2 { margin: 0 0 4px; font-size: 18px; }\n\n/* relative: stays where it is, but becomes the reference point\n   for absolute children. */\n.card {\n  position: relative;\n  width: 320px;\n  padding: 12px 16px;\n  margin-bottom: 24px;\n  background-color: white;\n  border: 2px solid #1d4e89;\n}\n\n/* absolute: removed from the flow and placed by top/right\n   inside the nearest positioned ancestor (the card). */\n.badge {\n  position: absolute;\n  top: -10px;\n  right: -10px;\n  padding: 2px 8px;\n  background-color: #a33a00;\n  color: white;\n  border-radius: 10px;\n}\n\n.schedule { height: 120px; width: 320px; overflow-y: auto; border: 2px solid #1d4e89; }\n.schedule p { margin: 6px 12px; }\n\n/* sticky: scrolls normally until it reaches top: 0, then stays there. */\n.schedule h2 { position: sticky; top: 0; padding: 6px 12px; background-color: #1d4e89; color: white; }","summary":"The position property changes how an element is placed. relative keeps it in place but makes it a reference point, absolute places it inside that reference point, and sticky keeps it on screen while you scroll.","notes":["The badge uses top: -10px and right: -10px, so it hangs over the card's top right corner.","Without position: relative on .card, the badge would be placed relative to the page instead.","Scroll inside the Fall schedule box: the blue heading stays at the top because of position: sticky."],"pitfall":"Setting position: sticky with no top value. It then behaves like a normal element and never sticks.","keywords":["position","relative","absolute","fixed","sticky","top","right","z-index","badge","overflow"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"media-queries":{"code":"body { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin: 0 0 8px; color: #1d4e89; }\n\n.size { margin: 0 0 12px; font-weight: bold; color: #a33a00; }\n\n/* Mobile first: these are the phone styles, used at every width\n   unless a media query below changes them. */\n.projects { display: grid; grid-template-columns: 1fr; gap: 12px; }\n.projects article { padding: 16px; background-color: white; border: 2px solid #1d4e89; }\n.tablet, .desktop { display: none; }\n\n/* 500px and wider: two columns. */\n@media (min-width: 500px) {\n  .projects { grid-template-columns: repeat(2, 1fr); }\n  .phone { display: none; }\n  .tablet { display: block; }\n}\n\n/* 900px and wider: four columns. This rule comes last so it wins. */\n@media (min-width: 900px) {\n  .projects { grid-template-columns: repeat(4, 1fr); }\n  .tablet { display: none; }\n  .desktop { display: block; }\n}","summary":"A media query applies CSS only when a condition is true, such as the screen being at least 500px wide. Start with phone styles, then add min-width queries for bigger screens.","notes":["The preview is about 640px wide, so (min-width: 500px) is true and (min-width: 900px) is false: you see two columns.","Narrower than 500px (a phone), neither query applies: one column. 900px or wider, both apply and the later one wins: four columns.","To test it, open the page in your browser and drag the window narrower and wider."],"pitfall":"Putting the @media block above the normal rules. The normal rule comes later, so it wins and the media query seems to do nothing.","keywords":["@media","media query","min-width","max-width","breakpoint","responsive","mobile first","screen width"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"custom-properties":{"code":"/* Custom properties start with two dashes. On :root they are\n   available to every element on the page. */\n:root {\n  --club-blue: #1d4e89;\n  --paper: #fdfaf3;\n  --space: 12px;\n  --radius: 8px;\n}\n\nbody {\n  font-family: system-ui, sans-serif;\n  margin: 24px;\n  background-color: var(--paper);\n}\n\nh1 { margin-top: 0; color: var(--club-blue); }\n\n.teams { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space); }\n\n/* var(--accent, var(--club-blue)) uses --accent if it is set,\n   and falls back to --club-blue if it is not. */\n.team {\n  padding: var(--space);\n  border-radius: var(--radius);\n  border-top: 8px solid var(--accent, var(--club-blue));\n  background-color: white;\n}\n.team h2 { margin: 0; font-size: 18px; color: var(--accent, var(--club-blue)); }\n\n/* Setting a variable on one element changes it for that element\n   and its children only. */\n.games { --accent: #a33a00; }\n.robots { --accent: #2e7d32; }","summary":"Custom properties (CSS variables) store a value with a name like --club-blue. Read the value with var(--club-blue). Change it in one place and every rule that uses it updates.","notes":["Variables set on :root work everywhere on the page, so they are a good home for the site's colors and spacing.","The second value in var(--accent, var(--club-blue)) is a fallback. The web card has no --accent, so it uses blue.",".games { --accent: #a33a00; } changes the accent only inside the games card. The heading and border both follow it."],"pitfall":"Leaving off the dashes or var(): color: club-blue; or color: --club-blue; is invalid and the browser ignores it.","keywords":["custom properties","css variables","var()","--",":root","fallback","theme","design tokens"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"transitions":{"code":":root { --blue: #1d4e89; --paper: #fdfaf3; }\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: var(--paper); }\nh1 { margin-top: 0; color: var(--blue); }\n\n.meetings { list-style: none; padding: 0; }\n\n.meetings a {\n  display: block;\n  margin-bottom: 8px;\n  padding: 12px 16px;\n  border: 2px solid var(--blue);\n  border-radius: 6px;\n  color: var(--blue);\n  background-color: white;\n  /* Animate these properties over 0.25 seconds when they change. */\n  transition: background-color 0.25s ease, color 0.25s ease, box-shadow 0.25s ease;\n}\n\n/* The transition is on the normal rule, so it runs both ways: in and out. */\n.meetings a:hover, .meetings a:focus-visible {\n  background-color: var(--blue);\n  color: white;\n  box-shadow: 0 4px 10px rgb(0 0 0 / 25%);\n}\n\nbutton { font: inherit; padding: 8px 20px; border: none; border-radius: 4px;\n  background-color: #a33a00; color: white; transition: background-color 0.4s; }\nbutton:hover { background-color: #2e7d32; }\n\n/* Some people turn on \"reduce motion\" in their system settings.\n   Respect it by switching changes to instant. */\n@media (prefers-reduced-motion: reduce) {\n  * { transition: none !important; }\n}","summary":"A transition animates a property from its old value to its new value, for example when hover changes a color. You list which properties to animate and how long to take.","notes":["transition: background-color 0.25s ease means: when background-color changes, take 0.25 seconds to get there.","Put transition on the normal rule, not on :hover. Then the change animates on the way in and on the way out.","@media (prefers-reduced-motion: reduce) turns the animation off for people who set that option in their system."],"pitfall":"Writing transition: all. It also animates properties you did not mean to change, such as layout sizes, which can look jumpy and slow the page.","keywords":["transition","transition-duration","ease","hover","animation","prefers-reduced-motion","reduced motion","timing function"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"keyframes":{"code":":root { --blue: #1d4e89; --green: #2e7d32; }\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin-top: 0; color: var(--blue); }\n\n/* @keyframes names an animation and lists the steps. */\n@keyframes pulse {\n  from { opacity: 1; }\n  to { opacity: 0.25; }\n}\n@keyframes fill-up { from { width: 0; } }\n\n.dot {\n  display: inline-block;\n  width: 12px;\n  height: 12px;\n  border-radius: 50%;\n  background-color: var(--green);\n  /* name, length, timing, repeat forever, go back and forth */\n  animation: pulse 1.2s ease-in-out infinite alternate;\n}\n\n.track { width: 320px; height: 20px; background-color: #e3ddd0; border-radius: 10px; }\n\n/* The final width is set here. The animation only runs from 0 to it. */\n.fill {\n  width: 75%;\n  height: 100%;\n  border-radius: 10px;\n  background-color: var(--blue);\n  animation: fill-up 1.5s ease-out;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .dot, .fill { animation: none; }\n}","summary":"@keyframes describes the steps of an animation, and the animation property runs it on an element. Unlike a transition, it does not need a state change like hover to start.","notes":["animation: pulse 1.2s ease-in-out infinite alternate fades the dot down and back up forever.","fill-up has only a from step. The to step is the element's normal width (75%), so the bar ends at 18 of 24.","With reduced motion turned on in the system settings, the animations stop and the bar shows at 75% right away."],"pitfall":"Misspelling the animation name, such as animation: pluse 1s. Nothing moves and there is no error message.","keywords":["@keyframes","animation","animation-name","animation-duration","infinite","alternate","from","to","prefers-reduced-motion","loading bar"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"accessible-markup":{"code":":root { --blue: #1d4e89; --orange: #a33a00; }\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin: 0 0 8px; color: var(--blue); font-size: 24px; }\nimg { display: block; margin-bottom: 12px; }\n\nlabel { display: block; font-weight: bold; margin-bottom: 4px; }\ninput, button { font: inherit; }\n#team { padding: 6px; width: 240px; border: 2px solid #555; }\n\n/* Hint text needs enough contrast to read: #555 on this background passes WCAG AA. */\n.hint { margin: 4px 0 12px; color: #555; font-size: 0.9rem; }\n\nfieldset { border: 2px solid #c9c2b4; width: 280px; }\nlegend { font-weight: bold; }\nfieldset label { font-weight: normal; }\n\n/* Make radio buttons larger so they are easier to click or tap. */\ninput[type=\"radio\"] { width: 18px; height: 18px; vertical-align: middle; }\n\nbutton {\n  margin-top: 12px;\n  padding: 8px 20px;\n  border: none;\n  background-color: var(--blue);\n  color: white;\n}\n\n/* A strong focus ring so keyboard users can always see where they are.\n   Press Tab in the preview to see it. */\n:focus-visible { outline: 3px solid var(--orange); outline-offset: 2px; }","summary":"CSS can make a page easier or harder to use. Keep text contrast high, make click targets big enough, and never hide the keyboard focus outline.","notes":[":focus-visible with no element before it applies to anything focused by the keyboard. Press Tab in the preview to move through the fields.","Gray hint text is only readable if it is dark enough. WCAG AA asks for a contrast ratio of at least 4.5 to 1 for normal text.","Larger radio buttons (18px) are easier to hit with a finger or an unsteady mouse."],"pitfall":"Writing :focus { outline: none; } because the outline looks ugly. Keyboard users then cannot tell which field they are in.","keywords":["accessibility","focus-visible","outline","contrast","wcag","target size","fieldset","legend","a11y"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"grid-areas":{"code":"body { font-family: system-ui, sans-serif; margin: 16px; background-color: #fdfaf3; }\n\n/* Each quoted string is one row. Each word is one column.\n   Repeating a name makes that area cover more than one cell. */\n.page {\n  display: grid;\n  grid-template-columns: 140px 1fr 160px;\n  grid-template-areas:\n    \"header header header\"\n    \"nav    main   aside\"\n    \"footer footer footer\";\n  gap: 8px;\n}\n\n/* grid-area connects each element to a name from the map above. */\nheader { grid-area: header; }\nnav    { grid-area: nav; }\nmain   { grid-area: main; }\naside  { grid-area: aside; }\nfooter { grid-area: footer; }\n\nheader, nav, main, aside, footer { padding: 12px; border-radius: 6px; background-color: white; border: 2px solid #c9c2b4; }\nheader { background-color: #1d4e89; color: white; font-weight: bold; font-size: 20px; }\nnav a { display: block; color: #1d4e89; margin-bottom: 6px; }\nmain h1 { margin: 0 0 6px; font-size: 22px; }\nmain p { margin: 0; }\naside { background-color: #ffe9d6; }\nfooter { color: #555; font-size: 14px; }","summary":"grid-template-areas lets you draw a layout with names. Each string is a row, each name is a cell, and grid-area puts an element in the cells with its name.","notes":["\"header header header\" makes the header span all three columns. The footer does the same in the last row.","The middle row \"nav main aside\" places the three middle regions side by side, sized by grid-template-columns.","The shared card style is listed first. The header and aside rules come after it, so their background colors win the tie."],"pitfall":"Drawing an area that is not a rectangle, such as an L shape. The browser rejects the whole grid-template-areas value and the items stack in order.","keywords":["grid-template-areas","grid-area","named areas","page layout","grid","header","sidebar","footer","grid layout"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"transforms":{"code":"body { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin-top: 0; color: #1d4e89; }\n\n.board { display: flex; gap: 24px; padding: 12px 0; }\n\n.note {\n  flex: 1;\n  padding: 12px;\n  background-color: #fff6b3;\n  box-shadow: 0 2px 6px rgb(0 0 0 / 20%);\n  transition: transform 0.2s ease;\n}\n.note h2 { margin: 0 0 4px; font-size: 16px; font-family: monospace; }\n.note p { margin: 0; }\n\n/* rotate turns the element. Negative angles turn it counterclockwise. */\n.rotate { transform: rotate(-4deg); }\n\n/* translate moves it right and down (x, y) from where it would be.\n   Its space in the layout stays where it was. */\n.move { transform: translate(0, 16px); }\n\n/* scale changes its size. 1 is normal, 1.1 is 10% bigger. */\n.grow { transform: scale(0.9); }\n\n/* On hover, every note scales up. This replaces its own transform,\n   so the rotated note straightens out. */\n.note:hover { transform: scale(1.1); }\n\n@media (prefers-reduced-motion: reduce) {\n  .note { transition: none; }\n}","summary":"transform changes how an element is drawn: rotate() turns it, translate() moves it, and scale() resizes it. The rest of the layout acts as if the element had not moved.","notes":["rotate(-4deg) tilts the first note 4 degrees counterclockwise.","translate(0, 16px) moves the second note down 16px, but the board still saves space for it in its original spot.","A new transform replaces the old one. To keep both, list them together: transform: rotate(-4deg) scale(1.1);"],"pitfall":"Writing two transform declarations in one rule, like transform: rotate(5deg); transform: scale(2);. The second replaces the first, so the element only scales.","keywords":["transform","rotate","translate","scale","deg","transform-origin","hover","skew"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"dark-mode":{"code":"/* Light theme colors. These are the default. */\n:root {\n  --bg: #fdfaf3;\n  --card: #ffffff;\n  --text: #222222;\n  --muted: #555555;\n  --accent: #1d4e89;\n  --border: #c9c2b4;\n}\n\n/* When the device is set to dark mode, swap the values. Every rule\n   below uses the variables, so nothing else has to change. */\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #14171c;\n    --card: #1f242c;\n    --text: #e8e6e1;\n    --muted: #b0aca4;\n    --accent: #8db8ef;\n    --border: #3a414c;\n  }\n}\n\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: var(--bg); color: var(--text); }\nh1 { margin-top: 0; color: var(--accent); }\na { color: var(--accent); }\n\n.card { padding: 16px; background-color: var(--card); border: 2px solid var(--border); border-radius: 8px; }\n.card h2 { margin-top: 0; }\nlabel { display: block; margin-bottom: 4px; color: var(--muted); }\ninput { font: inherit; padding: 6px; width: 260px; }","summary":"@media (prefers-color-scheme: dark) applies CSS only when the device is in dark mode. Store the colors in custom properties, then change only the variables inside that query.","notes":["The preview uses the theme your system is set to. Change your system setting to see the other theme.","Dark mode is not just black and white swapped. The accent is a lighter blue (#8db8ef) so it stays readable on a dark background.","The input gets dark colors automatically because of the color-scheme meta tag in the HTML."],"pitfall":"Changing the background to dark but forgetting a color set somewhere else, such as a link color. That text ends up dark on dark and unreadable.","keywords":["dark mode","prefers-color-scheme","light mode","theme","custom properties","color-scheme","media query"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"fluid-type":{"code":":root { --blue: #1d4e89; }\nbody { font-family: system-ui, sans-serif; margin: 0; background-color: #fdfaf3; }\n\n/* clamp(MIN, PREFERRED, MAX): use the preferred value, but never go\n   below MIN or above MAX. vw is 1% of the window width. */\nh1 {\n  margin: 0;\n  font-size: clamp(1.75rem, 1rem + 4vw, 3.5rem);\n}\n\n.hero {\n  /* Padding grows with the window too, between 16px and 64px. */\n  padding: clamp(16px, 5vw, 64px);\n  background-color: var(--blue);\n  color: white;\n}\n\n.hero p {\n  margin: 4px 0 0;\n  font-size: clamp(1rem, 0.9rem + 0.5vw, 1.25rem);\n}\n\n/* min() picks the smaller value: full width on small screens,\n   but never wider than 60 characters, so lines stay easy to read. */\n.details {\n  width: min(100% - 32px, 60ch);\n  margin: 16px auto;\n  line-height: 1.5;\n}","summary":"clamp(min, preferred, max) picks a size that follows the window width but stays between a minimum and a maximum. It replaces several media queries with one line.","notes":["In the preview (about 640px wide), 1rem + 4vw = 16 + 25.6 = 41.6px for the h1. That is between the min (28px) and max (56px), so 41.6px is used.","At 320px wide the formula gives 28.8px. At 1200px it gives 64px, so the max of 3.5rem (56px) is used instead.","Mixing rem and vw in the middle value (1rem + 4vw) keeps text growing when someone zooms in, which vw alone does not do."],"pitfall":"Using only vw for font size (font-size: 5vw). Text becomes tiny on phones and huge on wide screens, and browser zoom has no effect on it.","keywords":["clamp","fluid typography","vw","viewport units","min","max","responsive text","rem","ch"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"container-queries":{"code":"body { font-family: system-ui, sans-serif; margin: 16px; background-color: #fdfaf3; }\n\n/* Wide main column, narrow sidebar. */\n.layout { display: grid; grid-template-columns: 2fr 1fr; gap: 16px; }\n\n/* container-type: inline-size makes each slot a container that its\n   children can measure. (Container queries are new: 2023 in all browsers.) */\n.slot { container-type: inline-size; }\n\n.label { margin: 0 0 6px; font-size: 13px; color: #a33a00; font-family: monospace; }\n\n/* Default card layout (narrow): avatar above the text. */\n.member {\n  padding: 12px;\n  background-color: white;\n  border: 2px solid #1d4e89;\n  border-radius: 8px;\n}\n.avatar { width: 48px; height: 48px; }\n.member h2 { margin: 4px 0; font-size: 18px; }\n.member p { margin: 0; }\n\n/* When the nearest container is at least 300px wide,\n   put the avatar beside the text and make it bigger. */\n@container (min-width: 300px) {\n  .member {\n    display: flex;\n    gap: 16px;\n    align-items: center;\n  }\n  .avatar { width: 72px; height: 72px; flex-shrink: 0; }\n  .member h2 { font-size: 22px; }\n}","summary":"@container applies styles based on the width of the element's container instead of the whole screen. Mark a parent with container-type: inline-size, then write @container (min-width: ...) rules for its children.","notes":["In the preview, main is about 395px wide, so (min-width: 300px) is true and its card is a row. The aside is about 195px wide, so its card stays stacked.","A media query could not do this: both cards are on the same screen, at the same screen width.","If the whole page gets narrow enough that main is under 300px, its card stacks too."],"pitfall":"Setting container-type on the card itself and querying it from the card's own rule. An element cannot respond to its own size; the container must be an ancestor.","keywords":["@container","container queries","container-type","inline-size","responsive components","media query","component"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"has-selector":{"code":":root { --blue: #1d4e89; --green: #2e7d32; --orange: #a33a00; }\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin-top: 0; color: var(--blue); }\n\n.checklist { list-style: none; padding: 0; }\n.checklist li { padding: 6px 10px; margin-bottom: 4px; border-left: 4px solid #c9c2b4; }\n\n/* li:has(input:checked) matches an li that CONTAINS a checked input.\n   Before :has(), CSS could only style children, never the parent.\n   (:has() is new: in all major browsers since late 2023.) */\n.checklist li:has(input:checked) {\n  border-left-color: var(--green);\n  background-color: #e3f1e4;\n  color: #555;\n  text-decoration: line-through;\n}\n\n.cards { display: flex; gap: 12px; }\n.card {\n  position: relative;\n  flex: 1;\n  padding: 12px;\n  background-color: white;\n  border: 2px solid var(--blue);\n}\n.card h2 { margin: 0; font-size: 18px; }\n\n/* Only the card that has a .badge inside gets the orange border. */\n.card:has(.badge) { border-color: var(--orange); }\n\n.badge {\n  position: absolute; top: 10px; right: 10px;\n  padding: 2px 8px; border-radius: 10px;\n  background-color: var(--orange); color: white; font-size: 13px;\n}","summary":":has() selects an element based on what it contains. li:has(input:checked) means \"a list item that has a checked input inside it\", which lets you style a parent based on its children.","notes":["The first two checklist rows are crossed out because their checkboxes are checked. Click a row in the preview to toggle it.",".card:has(.badge) gives only the Web track card an orange border, because only it contains a badge.",":has() takes any selector inside the parentheses, including states like :checked, :focus, and :invalid."],"pitfall":"Writing li input:checked when you mean the li. That selects the checkbox, not the row, so the row style never changes.","keywords":[":has()","has selector","parent selector",":checked","checkbox","relational selector","contains"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"cascade-layers":{"code":"/* Declare the layer order once, from lowest to highest priority.\n   (@layer is in all major browsers since 2022.) */\n@layer base, components, utilities;\n\n@layer base {\n  body { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\n  button { font: inherit; padding: 8px 14px; margin: 0 6px 8px 0; border: none; border-radius: 4px; color: white; }\n\n  /* An id selector, but it is in the lowest layer... */\n  #join-web, #join-games { background-color: #666; }\n}\n\n@layer components {\n  /* ...so this plain class in a higher layer beats it.\n     Between layers, layer order wins over specificity. */\n  .btn { background-color: #1d4e89; }\n}\n\n@layer utilities {\n  .danger { background-color: #c62828; }\n}\n\n/* Styles outside any layer beat all layered styles. */\n.special { background-color: #2e7d32; }\nh1 { color: #1d4e89; }","summary":"@layer groups rules into layers with a set priority. A rule in a later layer beats a rule in an earlier layer, no matter how specific each selector is. Unlayered rules beat all layers.","notes":["@layer base, components, utilities; sets the order. Later in the list means higher priority.","The third button matches #join-games in base and .btn in components. The id is more specific, but components is the higher layer, so .btn wins and the button is blue.","Inside a single layer, the normal rules still apply: specificity first, then source order."],"pitfall":"Forgetting that unlayered CSS beats every layer. A leftover rule outside the layers can override your whole layer setup, even with a weak selector.","keywords":["@layer","cascade layers","layer order","specificity","cascade","unlayered","utilities","components","reset"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"dialog-popover":{"code":":root { --blue: #1d4e89; }\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin-top: 0; color: var(--blue); }\n\nbutton {\n  font: inherit;\n  padding: 6px 14px;\n  border: 2px solid var(--blue);\n  border-radius: 4px;\n  background-color: white;\n  color: var(--blue);\n}\n\n/* The browser centers popovers and hides them until opened.\n   (Popover is new: in all major browsers since 2024.) */\n[popover] {\n  width: 260px;\n  padding: 12px 16px;\n  border: 2px solid var(--blue);\n  border-radius: 8px;\n  box-shadow: 0 8px 24px rgb(0 0 0 / 25%);\n}\n[popover] p { margin-top: 0; }\n\n/* An open dialog without showModal() sits in the page where it is\n   written. position: static keeps it in the normal flow here. */\ndialog {\n  position: static;\n  margin: 20px 0 0;\n  max-width: 340px;\n  border: 2px solid var(--blue);\n  border-radius: 8px;\n}\ndialog h2 { margin-top: 0; }\n\n/* ::backdrop is the dimmed layer behind a modal dialog or popover. */\n::backdrop { background-color: rgb(0 0 0 / 30%); }","summary":"Popovers and dialogs come with default styles: the browser centers a popover and draws a border. You can restyle them like any element, and ::backdrop styles the layer behind them.","notes":["[popover] is an attribute selector that matches any element with the popover attribute, open or closed.","::backdrop dims the page behind an open popover. Click the button in the preview to see it. It also appears behind a dialog opened with showModal().","dialog { position: static; } keeps this non-modal dialog in the normal flow, below the button."],"pitfall":"Setting display: block on [popover]. That overrides the browser's display: none for closed popovers, so the popover is always visible.","keywords":["popover","dialog","::backdrop","backdrop","attribute selector","modal","overlay","box-shadow"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null},"scroll-snap":{"code":":root { --blue: #1d4e89; }\nbody { font-family: system-ui, sans-serif; margin: 24px; background-color: #fdfaf3; }\nh1 { margin: 0; color: var(--blue); }\n\n/* The gallery is a flex row that scrolls sideways. */\n.gallery {\n  display: flex;\n  gap: 16px;\n  overflow-x: auto;\n  padding-bottom: 12px;\n  /* x: snap while scrolling sideways. mandatory: always end on a snap point. */\n  scroll-snap-type: x mandatory;\n  /* Snap points sit 8px in from the edge, so the snapped card keeps a margin. */\n  scroll-padding-inline: 8px;\n}\n\n/* Each card is 70% of the gallery width, so part of the next card shows.\n   flex: none stops flexbox from shrinking the cards to fit. */\n.slide {\n  flex: none;\n  width: 70%;\n  padding: 16px;\n  box-sizing: border-box;\n  background-color: white;\n  border: 2px solid var(--blue);\n  border-radius: 8px;\n  /* Line up the card's left edge with the snap position. */\n  scroll-snap-align: start;\n}\n.slide h2 { margin: 0 0 6px; font-size: 20px; }\n.slide p { margin: 0; }\n\n.gallery:focus-visible { outline: 3px solid #a33a00; outline-offset: 4px; }\n\n@media (prefers-reduced-motion: no-preference) {\n  .gallery { scroll-behavior: smooth; }\n}","summary":"Scroll snap makes a scrolling container stop with an item lined up, instead of anywhere in between. Put scroll-snap-type on the container and scroll-snap-align on each item.","notes":["scroll-snap-type: x mandatory means sideways scrolling always comes to rest on a card. proximity would only snap when you stop close to one.","width: 70% shows part of the next card. That edge tells people there is more to scroll.","scroll-behavior: smooth is only turned on when the person has not asked for reduced motion."],"pitfall":"Putting scroll-snap-type on the cards instead of the scrolling container. Nothing snaps, and there is no error.","keywords":["scroll-snap-type","scroll-snap-align","scroll-padding","carousel","slider","overflow-x","mandatory","proximity","scroll-behavior","smooth scroll"],"stdin":"","output":null,"run":false,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":null,"filename":null}}}};
